import os
import json
import time
import re
from datetime import datetime
from urllib.parse import urljoin
from bs4 import BeautifulSoup
from playwright.sync_api import sync_playwright

# 配置常量
OUTPUT_DIR = "./output"
TARGET_URL = "https://www.businesswire.com/newsroom"
MAX_ITEMS = 5

def clean_html_content(html_content, base_url):
    """
    清洗HTML内容：
    1. 将相对路径转换为绝对路径
    2. 移除无用标签
    """
    if not html_content:
        return ""
    try:
        soup = BeautifulSoup(html_content, 'html.parser')

        # 修复图片链接
        for img in soup.find_all('img'):
            if img.get('src'):
                img['src'] = urljoin(base_url, img['src'])

        # 修复超链接
        for a in soup.find_all('a'):
            if a.get('href'):
                a['href'] = urljoin(base_url, a['href'])

        # 移除脚本和样式
        for script in soup(["script", "style", "iframe", "noscript"]):
            script.decompose()

        return str(soup)
    except Exception as e:
        print(f"内容清洗出错: {e}")
        return html_content

def parse_date(date_str):
    """
    解析日期字符串，支持多种格式
    """
    if not date_str:
        return datetime.now().strftime("%Y-%m-%d")

    try:
        # 移除干扰词
        clean_str = re.sub(r'\s+at\s+', ' ', date_str)
        clean_str = re.sub(r'\s+(ET|PT|CT|MT|GMT|BST).*$', '', clean_str).strip()

        # 格式：February 24, 2026
        match = re.search(r'([A-Za-z]+)\s+(\d{1,2}),\s+(\d{4})', clean_str)
        if match:
            dt_str = f"{match.group(1)} {match.group(2)} {match.group(3)}"
            try:
                return datetime.strptime(dt_str, "%B %d %Y").strftime("%Y-%m-%d")
            except ValueError:
                return datetime.strptime(dt_str, "%b %d %Y").strftime("%Y-%m-%d")

        # 格式：2/24/2026
        match = re.search(r'(\d{1,2})/(\d{1,2})/(\d{4})', clean_str)
        if match:
            return f"{match.group(3)}-{match.group(1).zfill(2)}-{match.group(2).zfill(2)}"

    except Exception as e:
        print(f"日期解析警告: {e}")

    # 默认返回当前日期
    return datetime.now().strftime("%Y-%m-%d")

def crawl_news():
    """
    爬取 Business Wire 新闻
    """
    articles = []

    with sync_playwright() as p:
        # 启动浏览器
        browser = p.chromium.launch(
            headless=True,
            args=[
                "--disable-blink-features=AutomationControlled", 
                "--no-sandbox",
            ]
        )
        context = browser.new_context(
            viewport={'width': 1920, 'height': 1080},
            user_agent="Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/122.0.0.0 Safari/537.36",
            locale="en-US",
            ignore_https_errors=True
        )

        page = context.new_page()

        try:
            print(f"正在访问列表页: {TARGET_URL}")
            # 使用 commit + wait_for_load_state 避免 strict timeout
            try:
                page.goto(TARGET_URL, wait_until="commit", timeout=30000)
                page.wait_for_load_state("domcontentloaded", timeout=30000)
            except Exception as e:
                print(f"页面加载提示: {e}")

            # 等待内容渲染
            page.wait_for_timeout(3000)

            # 获取所有新闻项链接
            # 策略：查找 href 包含 /news/home/ 的链接
            link_locators = page.locator("a[href*='/news/home/']").all()

            valid_links = []
            seen_urls = set()

            print(f"扫描到 {len(link_locators)} 个潜在链接")

            for loc in link_locators:
                if len(valid_links) >= MAX_ITEMS:
                    break
                try:
                    url = loc.get_attribute("href")
                    text = loc.inner_text().strip()
                    if url and url not in seen_urls and len(text) > 10:
                        full_url = urljoin(TARGET_URL, url)
                        seen_urls.add(full_url)
                        valid_links.append({
                            "url": full_url,
                            "title": text,
                            "element": loc
                        })
                except:
                    continue

            print(f"找到 {len(valid_links)} 个有效新闻项，准备抓取...")

            for idx, item in enumerate(valid_links):
                try:
                    title = item["title"]
                    full_url = item["url"]

                    # 尝试在列表页提取日期
                    date_str = ""
                    try:
                        # 向上查找日期
                        parent = item["element"].locator("xpath=..")
                        parent_text = parent.inner_text()
                        match = re.search(r'([A-Za-z]+\s+\d{1,2},\s+\d{4})', parent_text)
                        if match:
                            date_str = match.group(1)
                    except:
                        pass

                    formatted_date = parse_date(date_str)

                    print(f"[{idx+1}/{MAX_ITEMS}] 正在抓取: {title[:30]}...")

                    # 进入详情页
                    new_page = context.new_page()
                    try:
                        new_page.goto(full_url, wait_until="domcontentloaded", timeout=30000)

                        # 提取正文
                        content_html = ""
                        selectors = [
                            "div[itemprop='articleBody']",
                            ".bw-release-story",
                            ".ui-kit-press-release-content",
                            "article"
                        ]

                        for sel in selectors:
                            if new_page.locator(sel).count() > 0:
                                content_html = new_page.locator(sel).first.inner_html()
                                break

                        if not content_html:
                            content_html = new_page.locator("body").inner_html()

                        # 再次确认标题
                        if new_page.locator("h1").count() > 0:
                            title = new_page.locator("h1").first.inner_text().strip()

                        # 提取摘要
                        summary = ""
                        try:
                            meta_desc = new_page.locator("meta[name='description']").get_attribute("content")
                            if meta_desc:
                                summary = meta_desc
                        except:
                            pass

                        # 清洗内容
                        cleaned_content = clean_html_content(content_html, full_url)

                        article = {
                            "id": str(idx + 1),
                            "title": title,
                            "name": title,  # 【修复】添加 name 字段以满足 Schema 要求
                            "date": formatted_date,
                            "source": "Business Wire",
                            "author": "Business Wire",
                            "sourceUrl": full_url,
                            "summary": summary,
                            "content": cleaned_content
                        }

                        articles.append(article)
                        time.sleep(1)

                    except Exception as e:
                        print(f"抓取详情页失败 {full_url}: {e}")
                    finally:
                        new_page.close()

                except Exception as e:
                    print(f"处理列表项失败: {e}")
                    continue

        except Exception as e:
            print(f"爬取过程发生错误: {e}")
        finally:
            browser.close()

    return articles

def save_results(articles: list, output_dir: str):
    """保存结果为JSON"""
    if not os.path.exists(output_dir):
        os.makedirs(output_dir)

    timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
    filename = f"BusinessWire_News_{timestamp}.json"
    output_path = os.path.join(output_dir, filename)

    result = {
        "total": len(articles),
        "crawlTime": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
        "articles": articles
    }

    with open(output_path, 'w', encoding='utf-8') as f:
        json.dump(result, f, ensure_ascii=False, indent=2)

    print(f"已保存 {len(articles)} 条新闻到 {output_path}")

def main():
    print("开始爬取 Business Wire 新闻...")
    start_time = time.time()

    articles = crawl_news()

    if articles:
        save_results(articles, OUTPUT_DIR)
    else:
        print("未抓取到任何新闻数据。")

    end_time = time.time()
    print(f"任务完成，耗时: {end_time - start_time:.2f} 秒")

if __name__ == "__main__":
    main()
